cause.patch:
diff --git a/nginx.conf b/nginx.conf
@@ -1,9 +1,15 @@
 # Serves the Angular build behind the Caddy edge proxy; /api/, /admin/ and /static/ go to the backend there.
+# One client must not be able to flood the app shell; 5 requests per second with a burst
+# covers a full page load (bundles, fonts, images).
+limit_req_zone $binary_remote_addr zone=shell:10m rate=5r/s;
+
 server {
     listen 8080;
     server_name _;
     root /usr/share/nginx/html;
     index index.html;
     server_tokens off;
+    limit_req zone=shell burst=20 nodelay;
     # Activation and reset tokens are part of request paths; Caddy and Gunicorn keep no access log either.
     access_log off;
